#include <iostream>
#include <vector>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int size;
    cin >> size;
    vector<vector<long long>> grid(size + 1, vector<long long>(size + 1, 0));
    grid[0][0] = 0;
    const long long MOD = 1000000007;
    for (int i = 0; i <= size; i++) {
        for (int j = i; j <= size; j++) {
            if (i == 0 && j == 0) continue;
            if (i == 0) {
                grid[i][j] = (grid[i][j - 1] + ((i + j) & 1)) % MOD;
            } else if (j == 0) {
                grid[i][j] = (grid[i - 1][j] + ((i + j) & 1)) % MOD;
            } else {
                grid[i][j] = (grid[i - 1][j] + grid[i][j - 1] + ((i + j) & 1)) % MOD;
            }
        }
    }
    cout << grid[size][size] << "\n";
    return 0;
}
